"""F04.1 additive visualization decisions. Data contracts, no rendered graphics."""

DECISIONS = {}


def axis(symbol, unit, role, domain):
    return dict(symbol=symbol, label=symbol, unit=unit, role=role, domain=domain)


def only(n, reason, considered, plot="diagram_or_table"):
    DECISIONS[n] = dict(mode="2D_ONLY", reason=reason, alternative_considered=considered,
                        axes=[], definition=None, plot2d=plot, components=[],
                        presentation="existing_2d", gain=False, controls=[], bindings={},
                        invariants=["Contenuto, formule ed esempio F04 invariati."], edge_cases=[],
                        surface=False, trajectory=False, vectors=False, planes=[], projections=[],
                        animation=False, new_math=[])


def three(n, mode, reason, axes, definition, plot2d, components, *,
          surface=False, trajectory=False, planes=(), projections=(), animation=False,
          gain=False, controls=(), bindings=None, invariants=(), edges=(), presentation=None,
          new_math=(), geometry=False):
    DECISIONS[n] = dict(mode=mode, reason=reason, alternative_considered=None,
                        axes=axes, definition=definition, plot2d=plot2d,
                        components=components.split(), presentation=presentation or (
                            "3d_scene" if mode=="3D_PRIMARY" else "linked_toggle"),
                        gain=gain, controls=list(controls), bindings=bindings or {},
                        invariants=list(invariants), edge_cases=list(edges),
                        surface=surface, trajectory=trajectory, vectors=False,
                        planes=list(planes), projections=list(projections),
                        animation=animation, new_math=list(new_math), geometry=geometry)


def control(ident, symbol, low, high, default, unit, effect, *, integer=False):
    return dict(id=ident, symbol=symbol, min=low, max=high, default=default,
                unit=unit, integer=integer, origin="enrichment", effect=effect)


